<template>
  <div class="page-wrap" data-testid="research-page">
    <div class="page-heading"><div><span class="eyebrow">RESEARCH OVERVIEW</span><h1>A 股研究总览</h1><p>候选版本的研究证据与治理边界。</p></div><div class="heading-actions"><span class="as-of"><a-icon type="calendar" />DWD 基线截至 {{ dwdBase.through_date || catalog?.as_of || '—' }}</span><a-button icon="experiment" @click="$router.push('/candidates')">候选验证</a-button></div></div>
    <a-alert class="research-alert" type="warning" show-icon message="DWD 数据覆盖与候选回放分区是两套口径" :description="`研究用途，禁止实盘。当前 DWD 权威基线为 ${dwdBase.package_id || '—'}，截至 ${dwdBase.through_date || '—'}；页面指标来自候选各自的已发布回放证据，不代表已使用全部 DWD 日期。`" />
    <div class="metrics-grid" v-if="featuredCandidate">
      <MetricCard label="候选回放收益" :value="signed(featuredCandidate.total_return)" detail="简单累计收益，非 CAGR" tone="positive" />
      <MetricCard label="最大回撤" :value="percent(featuredCandidate.max_drawdown)" detail="预声明警戒线 25%" tone="neutral" />
      <MetricCard label="已闭合交易" :value="String(featuredCandidate.closed_trades)" :detail="`${featuredCandidate.operations} 次成交操作`" />
      <MetricCard label="Sharpe" :value="optionalNumber(featuredCandidate.sharpe, 3)" detail="开发集结果" />
    </div>
    <div class="overview-grid">
      <section class="panel chart-panel"><div class="panel-head"><div><h2>候选权益</h2><p>{{ featuredCandidate?.name }} · {{ evidenceWindow(featuredCandidate) }}</p></div><span class="status-tag accepted">回放成功</span></div><EquityChart :strategy="featuredCandidate" :equity-curve="featuredCurve" /><p class="chart-note">来自候选详情证据的真实月末权益；进入详情可查看完整成交账与运行血缘。</p></section>
      <section class="panel boundary-panel"><div class="panel-head"><div><h2>数据与验证边界</h2><p>DWD 基线、ADS 分区和候选证据</p></div><a-icon type="safety-certificate" /></div><dl><div><dt>DWD 权威基线</dt><dd>{{ dwdBase.build_id || '—' }}</dd></div><div><dt>DWD 截止日</dt><dd><span class="status-dot good"></span>{{ dwdBase.through_date || '—' }}</dd></div><div><dt>当前候选证据</dt><dd>{{ evidenceWindow(featuredCandidate) }}</dd></div><div><dt>仲裁分区</dt><dd>{{ partitionWindow('arbitration') }} · <span class="status-dot locked"></span>封存</dd></div><div><dt>永久盲集</dt><dd>{{ partitionWindow('permanent_blind') }} · <span class="status-dot locked"></span>封存</dd></div><div><dt>近期研究分区</dt><dd>{{ partitionWindow('recent_research') }} · 尚未回放</dd></div><div><dt>实盘授权</dt><dd><span class="status-dot bad"></span>未授权</dd></div></dl></section>
    </div>
    <section class="panel strategy-snapshot"><div class="panel-head"><div><h2>候选快照</h2><p>{{ strategies.length }} 个候选版本，包含 Quanthus 原生候选与已验证的 QuantDinger 信号候选</p></div><a-button type="link" @click="$router.push('/candidates')">全部候选 <a-icon type="arrow-right" /></a-button></div><div class="snapshot-list"><button v-for="item in strategies" :key="item.strategy_id" @click="openCandidate(item)"><span class="strategy-icon"><a-icon type="experiment" /></span><span class="snapshot-name"><b>{{ item.name }}</b><small>{{ item.strategy_id }}@{{ item.version }}</small></span><span :class="['status-tag', approvalClass(item)]">{{ approvalLabel(item) }}</span><span :class="item.total_return >= 0 ? 'positive' : 'negative'">{{ signed(item.total_return) }}</span><a-icon type="right" /></button></div></section>
  </div>
</template>
<script>
import MetricCard from '../components/MetricCard.vue'; import EquityChart from '../components/EquityChart.vue'; import { loadCandidate } from '../api'
export default { components: { MetricCard, EquityChart }, props: { catalog: Object }, data: () => ({ featuredDetail: null }), computed: { strategies () { return this.catalog?.strategies || [] }, featuredCandidate () { return this.strategies.find(item => item.strategy_id === 'candidate.market-breadth-trend-breakout') || this.strategies[0] || null }, featuredCurve () { return this.featuredDetail?.evidence?.equity_curve || [] }, dwdBase () { return this.catalog?.data_scope?.dwd_base || {} }, replayPartitions () { return this.catalog?.data_scope?.replay_partitions || {} } }, watch: { catalog: { immediate: true, handler () { this.loadFeaturedEvidence() } } }, methods: { async loadFeaturedEvidence () { if (!this.featuredCandidate) return; try { this.featuredDetail = await loadCandidate(this.featuredCandidate.strategy_id) } catch (_) { this.featuredDetail = null } }, percent: v => `${Number(v).toFixed(2)}%`, optionalNumber: (v, digits) => v == null ? '—' : Number(v).toFixed(digits), signed: v => `${v >= 0 ? '+' : ''}${Number(v).toFixed(2)}%`, shortDate: v => v ? v.slice(0, 7) : '—', openCandidate (item) { this.$router.push(`/candidates/${encodeURIComponent(item.strategy_id)}`) }, evidenceWindow (item) { const scope = item?.evidence_scope; return scope ? `${scope.decision_start} 至 ${scope.decision_end}` : '尚无回放证据' }, partitionWindow (name) { const scope = this.replayPartitions[name]; return scope ? `${this.shortDate(scope.start)} 至 ${this.shortDate(scope.end)}` : '—' }, approvalLabel (item) { const governance = item.approval?.governance?.state; if (governance === 'governance-admitted') return '治理准入'; if (governance === 'governance-rejected') return '治理拒绝'; if (governance === 'governance-under-review') return '治理审查中'; return ({ 'pending-review': '待复核', reviewing: '复核中', 'changes-requested': '待补证', 'review-passed': '复核通过', 'review-failed': '复核未通过' }[item.approval?.review?.state] || '待复核') }, approvalClass (item) { const value = this.approvalLabel(item); return value.includes('准入') || value.includes('通过') ? 'accepted' : value.includes('拒绝') || value.includes('失败') || value.includes('补证') ? 'rejected' : 'control' } } }
</script>
